head.script:
// ===== 리턴 값 출력 영역 =====
scwin.btn_clear_onclick = function (e) {
    $p.getComponentById("tbx_return").setValue("");
};

scwin.setReturnValue = function (strValue) {
    var objReturn = $p.getComponentById("tbx_return");
    objReturn.setValue(objReturn.getValue() + strValue);
    objReturn.setValue(objReturn.getValue() + "\n");
};

// ===== 결함 재현 (5.0 vs 6.0 동작 비교) =====
// 해당 InputBox 에 실제로 표시된 문자열을 읽어온다
scwin.getDisplayText = function (strId) {
    var objComp = $p.getComponentById(strId);
    var objDom = objComp.render;

    if (objDom && objDom.tagName === "INPUT") {
        return objDom.value;
    }

    var objInput = objDom ? objDom.querySelector("input") : null;
    return objInput ? objInput.value : "";
};

// 포커스 아웃 시 dataType / 저장값 / 화면 표시값을 출력
scwin.printValue = function (strId, strDataType) {
    var objComp = $p.getComponentById(strId);

    scwin.setReturnValue("[dataType=" + strDataType + "] getValue() : " + objComp.getValue()
        + " / 화면 표시값 : " + scwin.getDisplayText(strId));
};

scwin.target1_onblur = function (e) {
    scwin.printValue("target1", "number");
};

scwin.target2_onblur = function (e) {
    scwin.printValue("target2", "float");
};

scwin.target3_onblur = function (e) {
    scwin.printValue("target3", "bigDecimal");
};
